INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Jaký je rozdíl mezi val a var v Kotlinu?', 'val je měnná, var neměnná', 'val je neměnná, var je měnná', 'Obě jsou měnné', 'Obě jsou neměnné', 'b', 'val je read-only (neměnná reference), var lze reassignnout.', 1),
(@qfin, 'Co dělá operátor ?. v Kotlinu?', 'Násobení', 'Safe call — vrátí null místo výjimky', 'Logické AND', 'Vynutí non-null', 'b', 'Operátor ?. (safe call) zavolá metodu jen pokud receiver není null, jinak vrátí null.', 2),
(@qfin, 'Co automaticky generuje data class?', 'Pouze toString', 'equals, hashCode, toString, copy, componentN', 'Pouze constructor', 'Nic extra', 'b', 'data class automaticky generuje equals, hashCode, toString, copy a destructuring componentN.', 3),
(@qfin, 'Co je sealed class?', 'Třída, kterou nelze dědit', 'Třída s omezenou hierarchií podtříd', 'Abstraktní třída', 'Interface', 'b', 'Sealed class omezuje hierarchii — všechny podtřípy musí být ve stejném souboru a kompilátor zajistí exhaustive when.', 4),
(@qfin, 'Jaký je rozdíl mezi launch a async v coroutines?', 'Žádný', 'launch vrací Deferred, async nic', 'launch nic nevrací, async vrací Deferred', 'Obě vrací Deferred', 'c', 'launch spustí coroutine bez návratové hodnoty, async vrací Deferred<T> pro získání výsledku await().', 5),
(@qfin, 'Co je cold Flow v Kotlinu?', 'Flow, který emituje hodnoty neustále', 'Flow, který se vyhodnocuje lazly pro každého collector', 'Flow s jedním collector', 'Hot stream', 'b', 'Cold Flow se spustí znovu pro každého collector — každý collect vyhodnotí builder blok od začátku.', 6),
(@qfin, 'Co dělá remember v Jetpack Compose?', 'Zapomene stav', 'Uchová stav přes recompozici', 'Spustí coroutine', 'Naviguje na obrazovku', 'b', 'remember uchová hodnotu přes recompozice composable funkce, mutableStateOf navíc spustí recompozici při změně.', 7),
(@qfin, 'Který Ktor plugin zpracovává JSON serializaci?', 'ContentNegotiation s json()', 'JsonPlugin', 'SerializationModule', 'KtorJson', 'a', 'ContentNegotiation s kotlin-serialization-json pluginem zajišťuje automatickou JSON serializaci/deserializaci.', 8),
(@qfin, 'Jak definuješ tabulku v Exposed ORM?', 'class Users : DBTable', 'object Users : Table()', 'CREATE TABLE Users', 'Users.table()', 'b', 'V Exposed definuješ tabulku jako object dědící od Table s definovanými sloupci jako val vlastnosti.', 9),
(@qfin, 'K čemu slouží expect/actual v Kotlin Multiplatform?', 'K testování', 'expect deklaruje rozhraní v common, actual implementuje na platformě', 'K serializaci', 'K build konfiguraci', 'b', 'expect deklaruje deklaraci v commonMain, actual poskytuje platformní implementaci — základ KMP mechanismu.', 10);


